diff --git a/burpsy-go/internal/web/api_dom_engine.go b/burpsy-go/internal/web/api_dom_engine.go
new file mode 100644
index 00000000..194c36ce
--- /dev/null
+++ b/burpsy-go/internal/web/api_dom_engine.go
@@ -0,0 +1,106 @@
+package web
+
+import (
+	"encoding/json"
+	"net/http"
+	"strings"
+
+	"github.com/burpsy-go/burpsy/internal/scanner"
+)
+
+// The DOM engine, live (the runtime form of -dom).
+//
+// -dom was read once at startup, so a process started without it ran every DOM-based check as
+// capability-less until a restart, which mid-engagement drops the proxy's listeners. The scanners
+// hold one SwitchableBrowsers for their whole life; this route sets, changes or removes its engine.
+// The value takes the -dom forms: "" (none), "chrome" (launch and discover), "ws://…"/"wss://…"
+// (attach to a CDP server) or a browser binary. The process supplies the builder (cmd/burpsy), so
+// the browser leaves through the same egress route as every other send and a bad value is refused
+// with the same words as the flag. Setting an engine switches the DOM families on, as the flag did.
+// riskExecute: a binary path starts that program. Not persisted: like the flag it stands in for.
+
+// DOMEngineBuilder turns a -dom value into a provider ("" is never passed: it means none).
+type DOMEngineBuilder func(value string) (scanner.BrowserProvider, error)
+
+type domEngineView struct {
+	// Engine is the -dom value in force, "off" when there is none.
+	Engine string `json:"engine"`
+	// Configured says whether an engine is set; DOMChecks whether the scanner's DOM families are on.
+	Configured bool `json:"configured"`
+	DOMChecks  bool `json:"dom_checks"`
+}
+
+type domEngineReq struct {
+	Engine *string `json:"engine"`
+}
+
+// WithDOMSwitch attaches the switch the scanners hold and the builder for its values.
+func (s *Server) WithDOMSwitch(sw *scanner.SwitchableBrowsers, build DOMEngineBuilder) *Server {
+	s.domSwitch = sw
+	s.domBuild = build
+	return s
+}
+
+// domEngineLabel is the engine in force: the switch's when one is attached, else the -dom value.
+func (s *Server) domEngineLabel() string {
+	if s.domSwitch != nil {
+		return s.domSwitch.Label()
+	}
+	return s.domEngine
+}
+
+func (s *Server) viewDOMEngine() domEngineView {
+	v := domEngineView{Engine: "off", Configured: s.domSwitch.Configured()}
+	if l := s.domEngineLabel(); l != "" {
+		v.Engine = l
+	}
+	if sc := s.wiredScanner(); sc != nil {
+		snap := sc.ConfigSnapshot()
+		v.DOMChecks = snap.CheckDOM
+	}
+	return v
+}
+
+// handleDOMEngine serves GET/PUT /api/scanner/dom.
+func (s *Server) handleDOMEngine(w http.ResponseWriter, r *http.Request) {
+	switch r.Method {
+	case http.MethodGet, http.MethodPut:
+	default:
+		w.Header().Set("Allow", "GET, PUT")
+		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
+		return
+	}
+	if s.domSwitch == nil || s.domBuild == nil {
+		http.Error(w, "this process has no switchable DOM engine (it was built without one); restart with -dom", http.StatusServiceUnavailable)
+		return
+	}
+	if r.Method == http.MethodPut {
+		var req domEngineReq
+		if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<16)).Decode(&req); err != nil || req.Engine == nil {
+			http.Error(w, `body must be {"engine": ""|"chrome"|"ws://host:port/..."|"/path/to/browser"}`, http.StatusBadRequest)
+			return
+		}
+		value := strings.TrimSpace(*req.Engine)
+		var p scanner.BrowserProvider
+		if value != "" && value != "off" {
+			built, err := s.domBuild(value)
+			if err != nil {
+				http.Error(w, err.Error(), http.StatusBadRequest)
+				return
+			}
+			p = built
+		} else {
+			value = ""
+		}
+		if err := s.domSwitch.Set(p, value); err != nil && s.logger != nil {
+			// the new engine is in force; only the old browser's shutdown complained
+			s.logger.Sugar().Warnw("closing the previous DOM engine failed", "error", err)
+		}
+		if p != nil {
+			// a scanner built later from the capability recipe picks the engine up when it is wired
+			s.wiredScanner().EnableDOMChecks()
+		}
+	}
+	w.Header().Set("Content-Type", "application/json")
+	json.NewEncoder(w).Encode(s.viewDOMEngine())
+}
diff --git a/burpsy-go/internal/web/api_dom_engine_test.go b/burpsy-go/internal/web/api_dom_engine_test.go
new file mode 100644
index 00000000..f0593488
--- /dev/null
+++ b/burpsy-go/internal/web/api_dom_engine_test.go
@@ -0,0 +1,100 @@
+package web
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"net/http"
+	"testing"
+
+	"github.com/burpsy-go/burpsy/internal/core"
+	"github.com/burpsy-go/burpsy/internal/domexec"
+	"github.com/burpsy-go/burpsy/internal/scanner"
+	"go.uber.org/zap"
+)
+
+type stubEngine struct{ closed bool }
+
+func (e *stubEngine) Browser(context.Context) (*domexec.Browser, error) {
+	return nil, errors.New("stub")
+}
+func (e *stubEngine) Close() error { e.closed = true; return nil }
+
+func decodeDOM(t *testing.T, code int, body []byte) domEngineView {
+	t.Helper()
+	if code != http.StatusOK {
+		t.Fatalf("status %d: %s", code, body)
+	}
+	var v domEngineView
+	if err := json.Unmarshal(body, &v); err != nil {
+		t.Fatalf("decode %q: %v", body, err)
+	}
+	return v
+}
+
+// PUT /api/scanner/dom sets, replaces and removes the DOM engine of a running process: the scanner
+// that already holds the switch sees it, the DOM families are switched on with it, /api/stats reports
+// it, and a value the builder refuses changes nothing.
+func TestDOMEngineIsSetReplacedAndRemovedAtRuntime(t *testing.T) {
+	sw := scanner.NewSwitchableBrowsers()
+	built := map[string]*stubEngine{}
+	build := func(v string) (scanner.BrowserProvider, error) {
+		if v == "/no/such/browser" {
+			return nil, errors.New(`-dom "/no/such/browser" names neither a ws:// CDP endpoint nor a runnable browser`)
+		}
+		e := &stubEngine{}
+		built[v] = e
+		return e, nil
+	}
+	active := scanner.NewActiveScanner(core.NewTrafficStore(), zap.NewNop()).WithBrowserProvider(sw)
+	s := NewServer(core.NewTrafficStore(), core.NewScope()).WithScanner(active).WithDOMSwitch(sw, build)
+
+	rec := getJSON(t, s, "/api/scanner/dom")
+	if v := decodeDOM(t, rec.Code, rec.Body.Bytes()); v.Engine != "off" || v.Configured || v.DOMChecks {
+		t.Fatalf("a process started without -dom reports %+v", v)
+	}
+
+	rec = putJSON(t, s, "/api/scanner/dom", map[string]string{"engine": "chrome"})
+	if v := decodeDOM(t, rec.Code, rec.Body.Bytes()); v.Engine != "chrome" || !v.Configured || !v.DOMChecks {
+		t.Fatalf("after setting chrome: %+v", v)
+	}
+	if !active.DOMCapabilityConfigured() {
+		t.Fatal("the running scanner does not see the engine that was set")
+	}
+	rec = getJSON(t, s, "/api/stats")
+	var stats struct {
+		DOMEngine string `json:"dom_engine"`
+	}
+	_ = json.Unmarshal(rec.Body.Bytes(), &stats)
+	if stats.DOMEngine != "chrome" {
+		t.Fatalf("/api/stats reports dom engine %q, want chrome (%s)", stats.DOMEngine, rec.Body.Bytes())
+	}
+
+	rec = putJSON(t, s, "/api/scanner/dom", map[string]string{"engine": "/no/such/browser"})
+	if rec.Code != http.StatusBadRequest {
+		t.Fatalf("a refused value: status %d, want 400", rec.Code)
+	}
+	if sw.Label() != "chrome" || built["chrome"].closed {
+		t.Fatal("a refused value must leave the engine in force untouched")
+	}
+
+	rec = putJSON(t, s, "/api/scanner/dom", map[string]string{"engine": ""})
+	if v := decodeDOM(t, rec.Code, rec.Body.Bytes()); v.Engine != "off" || v.Configured {
+		t.Fatalf("after removing: %+v", v)
+	}
+	if !built["chrome"].closed || active.DOMCapabilityConfigured() {
+		t.Fatal("removing the engine must close it and leave the scanner without one")
+	}
+}
+
+func TestDOMEngineRefusesABadBodyAndAProcessWithoutASwitch(t *testing.T) {
+	s := NewServer(core.NewTrafficStore(), core.NewScope())
+	if rec := getJSON(t, s, "/api/scanner/dom"); rec.Code != http.StatusServiceUnavailable {
+		t.Fatalf("no switch: status %d, want 503", rec.Code)
+	}
+	sw := scanner.NewSwitchableBrowsers()
+	s = s.WithDOMSwitch(sw, func(string) (scanner.BrowserProvider, error) { return &stubEngine{}, nil })
+	if rec := putJSON(t, s, "/api/scanner/dom", map[string]bool{"engine": true}); rec.Code != http.StatusBadRequest {
+		t.Fatalf("bad body: status %d, want 400", rec.Code)
+	}
+}
diff --git a/burpsy-go/internal/web/api_interception.go b/burpsy-go/internal/web/api_interception.go
new file mode 100644
index 00000000..0d948557
--- /dev/null
+++ b/burpsy-go/internal/web/api_interception.go
@@ -0,0 +1,77 @@
+package web
+
+import (
+	"net/http"
+
+	"github.com/burpsy-go/burpsy/internal/proxy"
+)
+
+// The TLS interception switch, live.
+//
+// -intercept-tls was read once at startup: a process started without it tunnelled every CONNECT opaque
+// until it was restarted, which in the middle of an engagement means losing the proxy's listeners and
+// whatever the client had open. The policy already decided per connection whether to intercept (no
+// engine means tunnel), so the switch is that engine: on attaches the CA engine (loaded from, or
+// generated into, -ca-dir the first time), off detaches it. Off keeps the CA, so /ca.crt, import and
+// regenerate go on working and switching back on signs with the same CA the clients already trust.
+// Not persisted: like the flag it stands in for, it is this process's choice, and a restart takes the
+// flag again.
+
+type interceptionView struct {
+	Enabled bool   `json:"enabled"`
